/**
 * O cardume sem colisões — porte de `componentes/viz/cardume.js`.
 *
 * Milhares de peixes viram ao mesmo tempo e nenhum bate no outro. Não há chefe:
 * cada peixe só obedece a uma regra de distância com o vizinho. Perto demais e
 * eles se trombam; longe demais e o cardume deixa de ser um corpo só e vira
 * peixe solto — que é o que o predador procura.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, numeroDe, paleta, rodape, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const PEIXES = 26;
const COLUNAS = 6;

const cardume: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  // A fase de cada peixe, sorteada uma vez: é ela que evita o cardume respirar
  // em bloco, como um relógio.
  const fases = Array.from({ length: PEIXES }, () => Math.random() * Math.PI * 2);

  function peixe(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    direcao: number,
    cor: string,
    r: number,
  ): void {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(direcao);
    ctx.fillStyle = cor;

    ctx.beginPath();
    ctx.ellipse(0, 0, r, r * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(-r, 0);
    ctx.lineTo(-r - r * 0.8, -r * 0.5);
    ctx.lineTo(-r - r * 0.8, r * 0.5);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const distancia = Math.max(0, numeroDe(valores, 's', 0));
    const ok = info.ok === true;
    const apertado = distancia < numeroDe(info, 'alvoMin', 40);
    const solto = distancia > numeroDe(info, 'alvoMax', 70);

    titulo(ctx, L, A, ok ? 'Um corpo só' : 'A regra de distância');

    const linhas = Math.ceil(PEIXES / COLUNAS);
    // O espaçamento É o controle: é ele que aperta ou espalha a formação.
    const espaco = 0.06 + (distancia / 100) * 0.14;
    const cx = 0.5 + Math.sin(t * 0.5) * 0.06;
    const r = Math.min(L, A) * 0.028;
    const direcao = Math.sin(t * 0.5 + Math.PI / 2) * 0.25;

    for (let i = 0; i < PEIXES; i++) {
      const coluna = i % COLUNAS;
      const linha = Math.floor(i / COLUNAS);
      const fase = fases[i] ?? 0;

      // Apertado, o cardume treme: é o nervosismo antes da trombada.
      const tremor = apertado ? Math.sin(t * 6 + fase) * 0.012 : 0;
      const nx = cx + (coluna - (COLUNAS - 1) / 2) * espaco + tremor + Math.sin(t + fase) * 0.005;
      const ny =
        0.55 +
        (linha - (linhas - 1) / 2) * espaco +
        (solto ? Math.sin(fase) * ((distancia - 70) / 100) * 0.4 : 0);

      const x = nx * L;
      const y = ny * A;
      const colide = apertado && i % 3 === 0 && Math.sin(t * 6 + i) > 0.5;

      peixe(ctx, x, y, direcao, colide ? cor.erro : ok ? cor.verde : cor.azulClaro, r);

      if (colide) {
        ctx.strokeStyle = cor.erro;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(x, y, r * 2.2, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      'O cardume flui como um só, sem colisões ✔',
      apertado ? 'Perto demais: colisões no cardume.' : 'Espalhado demais: o cardume se desfaz.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default cardume;
